// src/pages/Login.jsx
import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import axios from "axios";
import { useTheme } from "../context/ThemeContext";

const Login = () => {
  const { colors } = useTheme();
  const navigate = useNavigate();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    try {
      const res = await axios.post("/api/v1/token/", {
        email,
        password,
      });

      localStorage.setItem("access", res.data.access);
      localStorage.setItem("user", JSON.stringify(res.data.user));

      navigate("/dashboard");
      window.location.reload();
    } catch {
      setError("Invalid email or password");
    }
  };

  return (
    <div
      style={{
        minHeight: "calc(100vh - 80px)",
        backgroundColor: colors.pageBg,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <form
        onSubmit={handleSubmit}
        style={{
          width: "100%",
          maxWidth: "420px",
          background: colors.cardBg,
          padding: "32px",
          borderRadius: "18px",
          color: colors.text,
        }}
      >
        <h2 style={{ textAlign: "center", marginBottom: "20px" }}>Log in</h2>

        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          style={{ width: "100%", marginBottom: "12px", padding: "10px" }}
        />

        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          style={{ width: "100%", marginBottom: "12px", padding: "10px" }}
        />

        {error && (
          <p style={{ color: "#f87171", fontSize: "13px" }}>{error}</p>
        )}

        <button
          type="submit"
          style={{
            width: "100%",
            padding: "10px",
            background: "#fbbf24",
            border: "none",
            borderRadius: "999px",
            fontWeight: 600,
            cursor: "pointer",
          }}
        >
          Log in
        </button>

        <p style={{ marginTop: "12px", fontSize: "13px", textAlign: "center" }}>
          Don&apos;t have an account?{" "}
          <Link to="/signup" style={{ color: "#fbbf24" }}>
            Sign up
          </Link>
        </p>
      </form>
    </div>
  );
};

export default Login;
